var isPalindrome = function(s) {
    let l = 0, r = s.length - 1;
    const isAlnum = c => /[a-zA-Z0-9]/.test(c);
    while (l < r) {
        while (l < r && !isAlnum(s[l])) l++;
        while (l < r && !isAlnum(s[r])) r--;
